mapper.select:
select a.id,b.action_id,a.client_id,a.client_name,a.risk_exposure,a.overdue_rent,a.cur_max_overdue_days,a.late_charge,a.project_sponsor_name,a.biz_dept_name,a.overdue,
b.user_name as process_person,b.`describe` as latest_progress,b.date as process_time from oc_overdue_collection
a
left join (SELECT t1.oc_id,t1.id as action_id,t1.describe,user.user_name,t1.date
FROM oc_overdue_collection_action t1
INNER JOIN (SELECT oc_id,max(`date`) as `date` FROM oc_overdue_collection_action GROUP BY oc_id) t2 ON t1.date =
t2.date and t1.oc_id = t2.oc_id
left join bifrost_user user on user.id = t1.create_by) b on a.id = b.oc_id


        and a.client_id = #{query.clientId}


        and a.biz_dept = #{query.bizDept}


        and a.project_sponsor = #{query.projectSponsor}


        and a.overdue = #{query.overdue}


        and
        (biz_dept IN

            #{item}

        OR project_sponsor = #{query.currentUserId}
        )


order by latest_progress desc
